671	    /// @dev Burns or transfers an investor position based on receiver's existing position.
672	    /// @param _from The address of the current owner.
673	    /// @param _to The address of the new owner.
674	    /// @param _positionId The ID of the position to transfer or burn.
675	    function _burnOrTransferInvestorPosition(address _from, address _to, uint256 _positionId) private {
676	        // Get the position ID of the receiver
677	        uint256 positionIdTo = s_investorPositionIds[_to];
678	
679	        // If the receiver already has a position, burn the transferred position
680	        // and update the existing position
681	        if (positionIdTo != 0) {
682	            // Load the investor positions
683	            InvestorPosition memory positionToBurn = s_investorPositions[_positionId];
684	            InvestorPosition storage positionToUpdate = s_investorPositions[positionIdTo];
685	
686	            // Verify that the updated position is not settled or refunded
687	            if (positionToUpdate.hasRefunded || positionToUpdate.hasSettled || !positionToUpdate.hasClaimedExcess) {
688	                revert Errors.LegionSale__UnableToMergeInvestorPosition(positionIdTo);
689	            }
690	
691	            // Update the existing position with the transferred values
692	            positionToUpdate.investedCapital += positionToBurn.investedCapital;
693	
694	            // Delete the burned position
695	            delete s_investorPositions[_positionId];
696	
697	            // Burn the investor position from the `from` address
698	            _burnInvestorPosition(_from);
699	        } else {
700	            // Transfer the investor position to the new address
701	            _transferInvestorPosition(_from, _to, _positionId);
702	        }
703	    }
